import csv, json, collections, sys

# Load data
data = []
with open('data_fixed.csv', newline='') as f:
    for row in csv.DictReader(f):
        data.append({
            'band': row['band'],
            'period_id': row['period_id'],
            'value': float(row['value'])
        })

# Determine all unique bands
all_bands = sorted({row['band'] for row in data})

# Build chronological list of period_ids (order of first appearance)
period_order = []
seen = set()
for row in data:
    pid = row['period_id']
    if pid not in seen:
        seen.add(pid)
        period_order.append(pid)

# Map each period_id to all rows up to and including that period
period_to_rows = {}
acc = []
idx = 0
for pid in period_order:
    while idx < len(data) and data[idx]['period_id'] == pid:
        acc.append(data[idx])
        idx += 1
    period_to_rows[pid] = list(acc)  # copy

# Read visits to predict
visits = []
with open('visits_to_predict.csv', newline='') as f:
    for line in f:
        pid = line.strip()
        if pid:
            visits.append(pid)

# Pre‑compute overall mean per band (fallback for periods with no prior data)
overall_sums = collections.defaultdict(float)
overall_counts = collections.defaultdict(int)
for row in data:
    overall_sums[row['band']] += row['value']
    overall_counts[row['band']] += 1
overall_mean = {b: overall_sums[b]/overall_counts[b] for b in all_bands}

# Build prediction dict
prediction = {}
for pid in visits:
    rows = period_to_rows.get(pid, [])
    # If there are no rows up to this period (unlikely), fall back to overall mean
    if not rows:
        pred = {b: round(overall_mean[b], 6) for b in all_bands}
    else:
        sums = collections.defaultdict(float)
        counts = collections.defaultdict(int)
        for r in rows:
            sums[r['band']] += r['value']
            counts[r['band']] += 1
        # Ensure every band has a value; if a band hasn't appeared yet, use overall mean
        pred = {}
        for b in all_bands:
            if counts[b]:
                pred[b] = round(sums[b] / counts[b], 6)
            else:
                pred[b] = round(overall_mean[b], 6)
    prediction[pid] = pred

rationale = ("For each visit (period_id) listed in visits_to_predict.csv, the forecast is the "
             "mean of that band’s observed values from the parcel’s own history up to and "
             "including that period.  If a band has no prior observations for a given visit, "
             "the overall mean for that band across the whole history is used as a fallback.")

output = {"prediction": prediction, "rationale": rationale}
with open('answer.json', 'w') as f:
    json.dump(output, f, indent=2)

print(json.dumps(output, indent=2))
