data = []
with open('data_fixed.csv', newline='') as f:
    for row in csv.DictReader(f):
        data.append({
            'band': row['band'],
            'period_id': row['period_id'],
            'value': float(row['value'])
        })

all_bands = sorted({r['band'] for r in data})

# Determine chronological order of period_ids
period_order = []
seen = set()
for r in data:
    pid = r['period_id']
    if pid not in seen:
        seen.add(pid)
        period_order.append(pid)

# Map each period_id to rows up to that period
period_to_rows = {}
acc = []
idx = 0
for pid in period_order:
    while idx < len(data) and data[idx]['period_id'] == pid:
        acc.append(data[idx])
        idx += 1
    period_to_rows[pid] = list(acc)

# Overall mean per band (fallback)
overall = collections.defaultdict(lambda: [0.0, 0])
for r in data:
    s, c = overall[r['band']]
    overall[r['band']] = [s + r['value'], c + 1]
overall_mean = {b: s/c for b, (s, c) in overall.items()}

# Read visits to predict (use only period_id column)
visits = []
with open('visits_to_predict.csv', newline='') as f:
    reader = csv.DictReader(f)
    for row in reader:
        visits.append(row['period_id'])

prediction = {}
for pid in visits:
    rows = period_to_rows.get(pid, [])
    if not rows:
        pred = {b: round(overall_mean[b], 6) for b in all_bands}
    else:
        sums = collections.defaultdict(float)
        counts = collections.defaultdict(int)
        for r in rows:
            sums[r['band']] += r['value']
            counts[r['band']] += 1
        pred = {}
        for b in all_bands:
            if counts[b]:
                pred[b] = round(sums[b] / counts[b], 6)
            else:
                pred[b] = round(overall_mean[b], 6)
    prediction[pid] = pred

rationale = ("For each visit (period_id) listed in visits_to_predict.csv, the forecast is the "
             "mean of that band’s observed values from the parcel’s own history up to and "
             "including that period. Missing prior observations fall back to the overall "
             "band mean.")

output = {"prediction": prediction, "rationale": rationale}
with open('answer.json', 'w') as f:
    json.dump(output, f, indent=2)

print(json.dumps(output, indent=2))
